/*
 * Here is an example of an expire function that may prolong
 * region life after some mods...
 */
/*ARGSUSED*/
/**
 * @param {*} p1 genericptr_t
 * @param {*} p2 genericptr_t
 * @returns {number} boolean
 */
export function expire_gas_cloud(p1, p2) {   // region.c:1046
    let reg = null, damage = 0, pass = 0, x = 0, y = 0;
    reg = $c.asRec(p1, $T.NhRegion, 96);
    damage = reg.arg.a_int;
    /* If it was a thick cloud, it dissipates a little first */
    if (damage >= 5) {
        damage = $c.div32(damage, 2);   /* It dissipates, let's do less damage */
        reg.arg.$copyFrom(cg.zeroany);
        reg.arg.a_int = damage;
        reg.ttl = 2;   /* Here's the trick : reset ttl */
        return FALSE;   /* THEN return FALSE, means "still there" */
    }
    /* The cloud no longer blocks vision.  cansee() checks shouldn't be made
       until all blocked spots have been unblocked, so we need two passes */
    for (pass = 1; pass <= (Blind() ? 1 : 2); pass = pass + 1 | 0) {
        for (x = reg.bounding_box.lx; x <= reg.bounding_box.hx; x = $c.i16(x + 1)) {
            for (y = reg.bounding_box.ly; y <= reg.bounding_box.hy; y = $c.i16(y + 1)) {
                if (inside_region(reg, x, y)) {
                    if (pass === 1) {
                        if (!does_block(x, y, $c.relem(svl.level.locations[x], y))) {
                            unblock_point(x, y);
                        }
                    } else {
                        /* pass==2 */
                        if (!u.uswallow) {
                            if (u_at(x, y)) {
                                gg.gas_cloud_diss_within = TRUE;
                            } else if (cansee(x, y)) {
                                gg.gas_cloud_diss_seen = gg.gas_cloud_diss_seen + 1 | 0;
                            }
                        }
                    }
                }
            }
        }
    }
    return TRUE;   /* OK, it's gone, you can free it! */
}
